var ErrNotFound = errors.New("not found")

func load() error {
	return fmt.Errorf("load: %v", ErrNotFound)
}

func main() {
	err := load()
	if errors.Is(err, ErrNotFound) {
		fmt.Println("404")
	} else {
		fmt.Println("500")
	}
}

type User struct{ Name string }

func lookup(id int) error {
	if id != 1 {
		return errors.New("no such user")
	}
	return nil
}

func loadUser(id int) (u User, err error) {
	if e := lookup(id); e != nil {
		return User{}, err
	}
	return User{Name: "Ada"}, nil
}
